// Cards move visually right to left. Autoplay pauses for hover, focus, interaction or reduced motion.
window.initVypaxShowcases=()=>document.querySelectorAll(".showcase").forEach(row=>{
if(row.dataset.motionReady)return;row.dataset.motionReady="true";const reduced=matchMedia("(prefers-reduced-motion: reduce)"),controls=document.querySelector('[data-controls="'+row.id+'"]'),pause=controls?.querySelector('[data-pause]');let stopped=reduced.matches,hover=false,focus=false,last=0,interactionUntil=0;
const isHome=document.body.classList.contains('homepage');if(isHome)row.dataset.direction='right';const originals=[...row.children];let cycle=0;
function prepare(){if(!isHome||reduced.matches||!originals.length)return;const gap=parseFloat(getComputedStyle(row).columnGap)||22;cycle=originals.reduce((sum,card)=>sum+card.getBoundingClientRect().width+gap,0);if(!cycle)return;row.querySelectorAll('[data-motion-clone]').forEach(node=>node.remove());let copies=Math.ceil(row.clientWidth/cycle)+2;for(let copy=0;copy<copies;copy++)for(const card of originals){const clone=card.cloneNode(true);clone.dataset.motionClone='true';clone.setAttribute('aria-hidden','true');clone.removeAttribute('id');clone.querySelectorAll('[id]').forEach(node=>node.removeAttribute('id'));clone.querySelectorAll('a,button,input,select,textarea,[tabindex]').forEach(node=>node.tabIndex=-1);row.append(clone);}row.scrollLeft=cycle;}
prepare();if(!isHome)row.scrollLeft=row.dataset.direction==='right'?row.scrollWidth-row.clientWidth:0;
if(pause){pause.textContent=stopped?'Play':'Pause';pause.setAttribute('aria-pressed',String(stopped));pause.onclick=()=>{stopped=!stopped;pause.textContent=stopped?'Play':'Pause';pause.setAttribute('aria-pressed',String(stopped))};}
for(const [selector,distance]of [['[data-prev]',-360],['[data-next]',360]])controls?.querySelector(selector)?.addEventListener('click',()=>{interactionUntil=performance.now()+8000;row.scrollBy({left:distance,behavior:reduced.matches?'auto':'smooth'})});
row.addEventListener('mouseenter',()=>hover=true);row.addEventListener('mouseleave',()=>hover=false);row.addEventListener('focusin',()=>focus=true);row.addEventListener('focusout',()=>focus=row.contains(document.activeElement));['wheel','touchstart','pointerdown','keydown'].forEach(event=>row.addEventListener(event,()=>{interactionUntil=performance.now()+8000},{passive:true}));
let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(()=>{if(row.isConnected)prepare()},200)});reduced.addEventListener('change',()=>{stopped=reduced.matches;if(stopped){row.querySelectorAll('[data-motion-clone]').forEach(node=>node.remove());row.scrollLeft=0;}else prepare();});
function tick(now){if(!row.isConnected)return;const dt=last?Math.min(now-last,60):0;last=now;if(!stopped&&!hover&&!focus&&!document.hidden&&now>interactionUntil&&row.scrollWidth>row.clientWidth){if(row.dataset.direction==='right'){if(row.scrollLeft<=1)row.scrollLeft=isHome&&cycle?row.scrollLeft+cycle:row.scrollWidth-row.clientWidth;else row.scrollLeft-=dt*.03;}else if(row.scrollLeft>=row.scrollWidth-row.clientWidth-1)row.scrollLeft=0;else row.scrollLeft+=dt*.03;}requestAnimationFrame(tick);}requestAnimationFrame(tick);
});

