const navMenus=[...document.querySelectorAll(".nav-dropdown")];navMenus.forEach(menu=>menu.addEventListener("toggle",()=>{if(menu.open)navMenus.forEach(other=>{if(other!==menu)other.open=false})}));document.addEventListener("click",event=>{if(!event.target.closest("#navigation"))navMenus.forEach(menu=>menu.open=false)});document.addEventListener("keydown",event=>{if(event.key==="Escape"){const opened=navMenus.find(menu=>menu.open);navMenus.forEach(menu=>menu.open=false);opened?.querySelector("summary").focus()}});

function renderHackathonDetails(){
const main=document.querySelector("main"),hero=main?.querySelector(":scope > .hack-hero"),portal=main?.querySelector(":scope > .portal-gate");
if(!hero||!portal)return;
const slug=location.pathname.split("/").pop().replace(/\.html$/,"");
function showError(message){
const notice=document.createElement("p");notice.className="hack-source-note";notice.setAttribute("role","alert");notice.textContent=message;portal.before(notice);
}
fetch("hackathons-data.json").then(response=>{
if(!response.ok)throw new Error("Could not load the published hackathon details.");
return response.json();
}).then(data=>{
const event=data.events.find(item=>item.slug===slug);
if(!event)throw new Error("No published details were found for this hackathon.");
const section=document.createElement("section");section.className="section hack-details";section.setAttribute("aria-labelledby","hack-details-title");
const heading=document.createElement("h2");heading.id="hack-details-title";heading.textContent="Event details";section.append(heading);
const summary=document.createElement("div");summary.className="hack-summary";
const factsCard=document.createElement("article");
const factsHeading=document.createElement("h3");factsHeading.textContent="At a glance";factsCard.append(factsHeading);
const facts=document.createElement("dl");facts.className="hack-detail-facts";
const factEntries=[["Status",event.status],["Entry fee",event.fee],["Team size",event.team],["Theme",event.theme],["Registration deadline",event.deadline],["Venue",event.venue],["Prize pool",event.prize]];
if(event.audience)factEntries.push(["Who can participate",event.audience]);
factEntries.forEach(([label,value])=>{const item=document.createElement("div"),term=document.createElement("dt"),detail=document.createElement("dd");term.textContent=label;detail.textContent=value;item.append(term,detail);facts.append(item)});
factsCard.append(facts);summary.append(factsCard);
const formatCard=document.createElement("article"),formatHeading=document.createElement("h3"),format=document.createElement("p");
formatHeading.textContent="Competition format";format.textContent=event.description;formatCard.append(formatHeading,format);summary.append(formatCard);section.append(summary);
const scheduleHeading=document.createElement("h3");scheduleHeading.textContent="Schedule";section.append(scheduleHeading);
if(event.stages.length){
const stages=document.createElement("ol");stages.className="hack-stage-list";
event.stages.forEach(([name,date,description],index)=>{const item=document.createElement("li"),number=document.createElement("span"),content=document.createElement("div"),title=document.createElement("h3"),time=document.createElement("p"),details=document.createElement("p");number.textContent=String(index+1).padStart(2,"0");title.textContent=name;time.textContent=date;details.textContent=description;content.append(title,time,details);item.append(number,content);stages.append(item)});
section.append(stages);
}else{const pending=document.createElement("p");pending.textContent="The event schedule has not yet been published.";section.append(pending)}
const awardsHeading=document.createElement("h3");awardsHeading.textContent="Awards";section.append(awardsHeading);
const awards=document.createElement("div");awards.className="hack-awards";
event.awards.forEach(([place,award])=>{const card=document.createElement("article"),title=document.createElement("h3"),details=document.createElement("p");title.textContent=place;details.textContent=award;card.append(title,details);awards.append(card)});
section.append(awards);
const note=document.createElement("p");note.className="hack-source-note";note.textContent=event.note;section.append(note);
const source=document.createElement("p");source.className="fine";source.append("Details checked on ",data.checkedOn," against the ");const sourceLink=document.createElement("a");sourceLink.href=data.source;sourceLink.target="_blank";sourceLink.rel="noopener noreferrer";sourceLink.textContent="official Vypax hackathon website";source.append(sourceLink,". Confirm current terms with the organizer before registering.");section.append(source);
const action=document.createElement("a");action.className="button";action.href=event.registration;action.target="_blank";action.rel="noopener noreferrer";action.textContent=event.cta;section.append(action);
portal.before(section);
}).catch(error=>{
console.error("Hackathon details could not be displayed:",error);
showError("Event details are temporarily unavailable. Please check the official Vypax hackathon website for current information.");
});
}
renderHackathonDetails();
